query_text:
UPDATE plan_smart.plan_master
SET eoh_boh_sync = {?eoh_boh_sync}
WHERE plan_code = {?plan_code}
AND is_deleted = false
RETURNING plan_code

$$$
			INSERT INTO meta_schema.tb_conditional_formatting_master
			( name,condition_formatting,remark)
			VALUES (
			    {?name},
			    {?condition_formatting}
			    {p1}
			)
			RETURNING id
			$$$.format(
			p1 = ", {?remark}" if len(parameter:remark) > 0 else ", null",
			)

$$$
                UPDATE meta_schema.tb_format_master 
                SET {p1} {p2} {p3} id = {?id}
                WHERE id = {?id}
                $$$.format(p1 = "name = {?name} ," if len(parameter:name) > 0 else "",
                           p2 = '''formatter = {?formatter} ,''' if parameter:formatter != -1 else "",
                           p3 = "remarks = {?remarks} ," if len(parameter:remarks) > 0 else "",
                       )

$$$
                UPDATE meta_schema.tb_lock_and_hold_def 
                SET display_label = {?display_name}
                where id = {?id}
                $$$

$$$
                UPDATE meta_schema.tb_conditional_formatting_master 
                SET {p1} {p2} {p3} id = {?id}
                WHERE id = {?id}
                $$$.format(p1 = "name = {?name} ," if len(parameter:name) > 0 else "",
                           p2 = "condition_formatting = {?value} ," if len(parameter:value) > 0 else "",
                           p3 = "remark = {?remark} ," if len(parameter:remark) > 0 else "",
                       )

$$$
                delete from meta_schema_new.tb_editableflow_master 
            where on_change_kpi_id = {?kpi};
                insert into meta_schema_new.tb_editableflow_master
                {p1}
                $$$.format(p1= " values {?editable_flow}" if len(parameter:editable_flow) > 0 else "select 1 where false")

$$$
                delete from meta_schema.tb_editableflow_master 
                where on_change_kpi_id = {?kpi};
                insert into meta_schema.tb_editableflow_master
                {p1}
                $$$.format(p1= " values {?editable_flow}" if len(parameter:editable_flow) > 0 else "select 1 where false")
